import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"A/B 创意批量测试","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"method/ab-testing.md","filePath":"method/ab-testing.md","lastUpdated":1787714366000}'),l={name:"method/ab-testing.md"};function o(i,t,h,s,n,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="a-b-创意批量测试" tabindex="-1">A/B 创意批量测试 <a class="header-anchor" href="#a-b-创意批量测试" aria-label="Permalink to &quot;A/B 创意批量测试&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">待补充</p><p>这一页还没有实战内容。下面是已经确定的问题结构和待填的位置。</p></div><h2 id="这一页要解决的问题" tabindex="-1">这一页要解决的问题 <a class="header-anchor" href="#这一页要解决的问题" aria-label="Permalink to &quot;这一页要解决的问题&quot;">​</a></h2><p>AI 最被低估的价值不是&quot;做得更好&quot;，而是&quot;做得更多&quot;。</p><p>传统流程里，一支广告只能做一个版本，因为拍摄成本高。AI 流程里，同一条创意做 8 个变体的边际成本极低——这让<strong>先投放、后判断</strong>成为可能：不再靠会议室里争论哪版更好，而是让数据说话。</p><p>但要真的跑通，需要解决三个问题：</p><ol><li>变体应该沿哪个维度变？（乱变等于没变量）</li><li>一次测几个版本才有统计意义？</li><li>看什么指标判断胜负？</li></ol><h2 id="已知的方向" tabindex="-1">已知的方向 <a class="header-anchor" href="#已知的方向" aria-label="Permalink to &quot;已知的方向&quot;">​</a></h2><p><strong>单变量原则。</strong> 一次只改一个维度，否则赢了也不知道是因为什么赢的。可测的维度按影响力排序，大致是：</p><table tabindex="0"><thead><tr><th>维度</th><th>举例</th><th>预期影响</th></tr></thead><tbody><tr><td>前 3 秒钩子</td><td>换开场镜头</td><td>最大</td></tr><tr><td>洞察角度</td><td>省时间 vs 不想将就</td><td>大</td></tr><tr><td>口播文案</td><td>同画面换旁白</td><td>中</td></tr><tr><td>视觉风格</td><td>冷调 vs 暖调</td><td>中</td></tr><tr><td>落点 CTA</td><td>换行动指令</td><td>小</td></tr></tbody></table><p><strong>从前 3 秒开始测。</strong> 完播率的差距主要在开头产生，先测钩子的性价比最高——而且只换第一个镜头，其余素材可以复用。</p><h2 id="待填内容" tabindex="-1">待填内容 <a class="header-anchor" href="#待填内容" aria-label="Permalink to &quot;待填内容&quot;">​</a></h2><h3 id="变体生产流程" tabindex="-1">变体生产流程 <a class="header-anchor" href="#变体生产流程" aria-label="Permalink to &quot;变体生产流程&quot;">​</a></h3><ul><li>怎么批量生成变体（工具、步骤）：</li><li>一次做几版：</li><li>单版成本（时间 / 消耗）：</li></ul><h3 id="测试设计" tabindex="-1">测试设计 <a class="header-anchor" href="#测试设计" aria-label="Permalink to &quot;测试设计&quot;">​</a></h3><ul><li>投放平台：</li><li>单版预算：</li><li>跑多久看数据：</li><li>判断胜负的主指标：</li><li>辅助指标：</li></ul><h3 id="结果记录" tabindex="-1">结果记录 <a class="header-anchor" href="#结果记录" aria-label="Permalink to &quot;结果记录&quot;">​</a></h3><p>用表格累积，跑得越多越有价值：</p><table tabindex="0"><thead><tr><th>项目</th><th>测试维度</th><th>A 版</th><th>B 版</th><th>胜出</th><th>关键指标差异</th><th>结论</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="沉淀下来的规律" tabindex="-1">沉淀下来的规律 <a class="header-anchor" href="#沉淀下来的规律" aria-label="Permalink to &quot;沉淀下来的规律&quot;">​</a></h3><p>跑够十几次以后，这里应该能写出一些跨项目成立的判断，比如&quot;什么类型的钩子在什么品类里更有效&quot;。</p><hr><p>写作格式参考 <a href="/templates/case-study">案例拆解模板</a>。</p>',23)])])}const p=a(l,[["render",o]]);export{b as __pageData,p as default};
